using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var modelName = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");
var endpoint = Environment.GetEnvironmentVariable("OPENAI_BASE_URL");

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(WebSearchTool.FetchPageAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// ---------------------------------------------------------------------------
// Chat client with automatic tool invocation
// ---------------------------------------------------------------------------
IChatClient innerClient = endpoint is not null
    ? new OpenAI.OpenAIClient(new System.ClientModel.ApiKeyCredential(apiKey),
          new OpenAI.OpenAIClientOptions { Endpoint = new Uri(endpoint) })
        .GetChatClient(modelName).AsIChatClient()
    : new OpenAI.OpenAIClient(apiKey).GetChatClient(modelName).AsIChatClient();

IChatClient agent = new ChatClientBuilder(innerClient)
    .UseFunctionInvocation()
    .Build();

var options = new ChatOptions { Tools = [.. tools] };

var history = new List<ChatMessage>
{
    new(ChatRole.System, """
        You are a research agent. Your job is to research a topic the user provides.

        Workflow:
        1. Search the web for relevant information using the SearchAsync tool.
        2. Open promising pages with FetchPageAsync to read details.
        3. Save key findings as notes using AddNote.
        4. When you have gathered enough information, call GetNotes to review
           everything, then provide a comprehensive summary to the user.

        Be thorough: perform multiple searches if needed and cross-reference
        sources. Always cite where you found information.
        """),
};

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       🔍  Research Agent Ready       ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine("Enter a topic to research (or 'quit' to exit):\n");

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("You> ");
    Console.ResetColor();
    var input = Console.ReadLine();
    if (string.IsNullOrWhiteSpace(input) || input.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    history.Add(new ChatMessage(ChatRole.User, input));

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("  [researching…]");
    Console.ResetColor();

    var response = await agent.GetResponseAsync(history, options);
    history.AddRange(response.Messages);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.Write("\nAgent> ");
    Console.ResetColor();
    Console.WriteLine(response.Text);
    Console.WriteLine();

    notebook.Clear();
}

Console.WriteLine("Goodbye!");

