/// <summary>Web search and page-fetching tools.</summary>
static partial class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for a query and return a list of result titles, URLs, and snippets.")]
    public static async Task<string> SearchAsync(
        [Description("The search query")] string query)
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine($"  🔎 Searching: {query}");
        Console.ResetColor();

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var html = await Http.GetStringAsync(
                $"https://html.duckduckgo.com/html/?q={encoded}");

            var results = ParseSearchResults(html);
            return results.Count == 0
                ? "No results found."
                : JsonSerializer.Serialize(results, JsonCtx.Default.ListSearchResult);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    [Description("Fetch the text content of a web page given its URL. Returns the first ~4000 characters.")]
    public static async Task<string> FetchPageAsync(
        [Description("The full URL of the page to fetch")] string url)
    {
        Console.ForegroundColor = ConsoleColor.Yellow;
        Console.WriteLine($"  🌐 Fetching: {url}");
        Console.ResetColor();

        try
        {
            var html = await Http.GetStringAsync(url);
            var text = StripHtml(html);
            return text.Length > 4000 ? text[..4000] + "\n…[truncated]" : text;
        }
        catch (Exception ex)
        {
            return $"Fetch failed: {ex.Message}";
        }
    }

    // --- helpers ---

    private static List<SearchResult> ParseSearchResults(string html)
    {
        var results = new List<SearchResult>();
        var linkPattern = LinkRegex();
        var matches = linkPattern.Matches(html);

        foreach (Match m in matches)
        {
            var rawUrl = WebUtility.HtmlDecode(m.Groups[1].Value);
            var title = StripHtmlTags(WebUtility.HtmlDecode(m.Groups[2].Value)).Trim();

            // DuckDuckGo wraps external URLs in a redirect; extract the real URL.
            if (rawUrl.Contains("uddg="))
            {
                var uddg = rawUrl.Split("uddg=").Last().Split('&').First();
                rawUrl = WebUtility.UrlDecode(uddg);
            }

            if (string.IsNullOrWhiteSpace(title) || !rawUrl.StartsWith("http"))
                continue;

            results.Add(new SearchResult(title, rawUrl));
            if (results.Count >= 8) break;
        }

        return results;
    }

    private static string StripHtml(string html)
    {
        // Remove script/style blocks, then tags, then collapse whitespace.
        var noScript = ScriptStyleRegex().Replace(html, " ");
        var noTags = TagRegex().Replace(noScript, " ");
        var decoded = WebUtility.HtmlDecode(noTags);
        return WhitespaceRegex().Replace(decoded, " ").Trim();
    }

    private static string StripHtmlTags(string s) =>
        TagRegex().Replace(s, "");

    [GeneratedRegex("""<a[^>]+href="([^"]+)"[^>]*class="result__a"[^>]*>(.*?)</a>""",
        RegexOptions.Singleline | RegexOptions.IgnoreCase)]
    private static partial Regex LinkRegex();

    [GeneratedRegex("""<(script|style)[^>]*>.*?</\1>""",
        RegexOptions.Singleline | RegexOptions.IgnoreCase)]
    private static partial Regex ScriptStyleRegex();

    [GeneratedRegex("<[^>]+>")]
    private static partial Regex TagRegex();

    [GeneratedRegex(@"\s{2,}")]
    private static partial Regex WhitespaceRegex();
}

