/// <summary>Simple note-taking tool the agent uses to collect findings.</summary>
class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save a research note. Use this to record important findings, facts, and source URLs.")]
    public string AddNote([Description("The note text to save")] string note)
    {
        _notes.Add(note);
        Console.ForegroundColor = ConsoleColor.Magenta;
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        Console.ResetColor();
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0) return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
            sb.AppendLine($"[{i + 1}] {_notes[i]}");
        return sb.ToString();
    }

    public void Clear() => _notes.Clear();
}

